120	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
121	    @Override
122	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
123	        // Prefer the structured address fields when present; the flat 'address' input remains accepted
124	        // for backward compatibility. When structured, the stored/returned address is the composed
125	        // normalized addressLine1 (with a single space and the normalized addressLine2 appended when
126	        // addressLine2 is present); otherwise it is the normalized flat 'address'.
127	        boolean structured = !isBlank(ownerFieldsDto.getAddressLine1());
128	        String addressLine1 = normalizeAddress(ownerFieldsDto.getAddressLine1());
129	        String addressLine2 = normalizeAddress(ownerFieldsDto.getAddressLine2());
130	        String address;
131	        if (structured) {
132	            address = addressLine2.isEmpty() ? addressLine1 : addressLine1 + " " + addressLine2;
133	        } else {
134	            address = normalizeAddress(ownerFieldsDto.getAddress());
135	        }
136	        List<String> missingFields = new ArrayList<>();
137	        if (isBlank(ownerFieldsDto.getFirstName())) {
138	            missingFields.add("firstName");
139	        }
140	        if (isBlank(ownerFieldsDto.getLastName())) {
141	            missingFields.add("lastName");
142	        }
143	        if (isBlank(address)) {
144	            missingFields.add("address");
145	        }
146	        if (isBlank(ownerFieldsDto.getCity())) {
147	            missingFields.add("city");
148	        }
149	        if (isBlank(ownerFieldsDto.getTelephone())) {
150	            missingFields.add("telephone");
151	        }
152	        if (!missingFields.isEmpty()) {
153	            throw new MissingOwnerFieldsException(missingFields);
154	        }
155	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
156	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
157	        HttpHeaders headers = new HttpHeaders();
158	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
159	        owner.setAddress(address);
160	        owner.setAddressLine1(structured ? addressLine1 : null);
161	        owner.setAddressLine2(structured && !addressLine2.isEmpty() ? addressLine2 : null);
162	        owner.setTelephone(telephone);
163	        validateEmailDomain(owner.getEmail());
164	        validatePostcode(owner.getPostcode(), owner.getRegion());
165	        // The household is keyed deterministically on (lastName, postcode): every owner receives the
166	        // same stable householdId as anyone sharing its normalized last name and postcode, without any
167	        // explicit link. This computed value drives duplicate detection and the household size.
168	        owner.setHouseholdId(householdIdFor(owner.getLastName(), owner.getPostcode()));
169	        // A second owner joining an existing household (same computed householdId) is rejected as a
170	        // household duplicate. Declaring 'sharesHousehold' only bypasses this block — it no longer
171	        // creates the link, since the link is now implicit in the computed householdId.
172	        if (!sharesHousehold && isHouseholdInUse(owner)) {
173	            throw new DuplicateIdentityException(owner.getIdentityKey());
174	        }
175	        // Remaining duplicate detection is consolidated into the single derived identity key: a create
176	        // is rejected when the new owner's whole identity key equals an existing owner's.
177	        if (isIdentityKeyInUse(owner.getIdentityKey())) {
178	            throw new DuplicateIdentityException(owner.getIdentityKey());
179	        }
180	        if (isCityAtCapacity(owner.getCity())) {
181	            throw new CityAtCapacityException(owner.getCity());
182	        }
183	        if (owner.getRegistrationDate() != null && owner.getRegistrationDate().isAfter(LocalDate.now())) {
184	            throw new FutureRegistrationDateException(owner.getRegistrationDate());
185	        }
186	        LocalDate effectiveDate = owner.getRegistrationDate() != null
187	            ? owner.getRegistrationDate() : LocalDate.now();
188	        LocalDate registrationDate = toBusinessDay(effectiveDate);
189	        if (isDailyRegistrationLimitReached(registrationDate)) {
190	            throw new DailyRegistrationLimitException(registrationDate);
191	        }
192	        owner.setRegistrationDate(registrationDate);
193	        owner.setCustomerCode(deduplicateCustomerCode(customerCodeFor(owner)));
194	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
195	        owner.setHouseholdSize(householdSizeAfterCreate(owner.getHouseholdId()));
196	        // A declared household member (one that set 'sharesHousehold' to join an existing household) is
197	        // not a suspected duplicate; otherwise fall back to the soft last-name + postcode match.
198	        Integer possibleDuplicateOf = sharesHousehold ? null : possibleDuplicateOf(owner);
199	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
200	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
201	        this.clinicService.saveOwner(owner);
202	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
203	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel(),
204	            owner.getMembershipNumber());
205	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
206	        ownerDto.setBulkSignupWarning(isBulkSignupWarning());
207	        headers.setLocation(UriComponentsBuilder.newInstance()
208	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
209	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
210	    }
