309	
310	    private static boolean isBlank(String value) {
311	        return value == null || value.isBlank();
312	    }
313	
314	    /**
315	     * The set of disposable email domains that owners may not register with. Compared
316	     * case-insensitively against the domain part of the supplied email.
317	     */
318	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS = java.util.Set.of(
319	        "mailinator.com", "tempmail.com", "guerrillamail.com");
320	
321	    /**
322	     * Rejects an owner whose email domain is on the disposable-domain blocklist
323	     * ({@code mailinator.com}, {@code tempmail.com}, {@code guerrillamail.com}). Email is optional:
324	     * a {@code null} or blank value, or one without an {@code '@'} domain part, is accepted here (the
325	     * {@code @Email} Bean Validation constraint governs format). The domain is compared
326	     * case-insensitively; the stored email is already lower-cased.
327	     *
328	     * @param email the owner's email (may be {@code null})
329	     * @throws DisposableEmailDomainException if the email's domain is on the blocklist
330	     */
331	    private static void validateEmailDomain(String email) {
332	        if (isBlank(email)) {
333	            return;
334	        }
335	        int at = email.lastIndexOf('@');
336	        if (at < 0) {
337	            return;
338	        }
339	        String domain = email.substring(at + 1).trim().toLowerCase(java.util.Locale.ROOT);
340	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
341	            throw new DisposableEmailDomainException(email);
342	        }
343	    }
344	
345	    /**
346	     * The fixed, region-keyed inclusive 4-digit postcode ranges. A region absent from this table
347	     * (locality {@code UNKNOWN}) imposes no range, so any 4-digit postcode is accepted there.
348	     */
349	    private static final java.util.Map<String, int[]> REGION_POSTCODES = java.util.Map.of(
350	        "NSW", new int[] {2000, 2099},
351	        "VIC", new int[] {3000, 3099},
352	        "QLD", new int[] {4000, 4099});
353	
354	    /**
355	     * Validates a supplied {@code postcode} against the owner's city region. Postcode is optional:
356	     * a {@code null} or blank value is accepted (validation only applies WHEN PRESENT). When
357	     * present, the value has already passed the 4-digit format check (Bean Validation on the
358	     * request body); this enforces that it falls within the inclusive range for the city's region
359	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known region imposes no range.
360	     *
361	     * @param postcode the supplied postcode (may be {@code null})
362	     * @param region the owner's locality/region derived from its city
363	     * @throws InvalidPostcodeException if the postcode is out of range for the region
364	     */
365	    private static void validatePostcode(String postcode, String region) {
366	        if (isBlank(postcode)) {
367	            return;
368	        }
369	        int[] range = REGION_POSTCODES.get(region);
370	        if (range == null) {
371	            return;
372	        }
373	        int value;
374	        try {
375	            value = Integer.parseInt(postcode);
376	        }
377	        catch (NumberFormatException e) {
378	            throw new InvalidPostcodeException(postcode);
379	        }
380	        if (value < range[0] || value > range[1]) {
381	            throw new InvalidPostcodeException(postcode);
382	        }
383	    }
384	
385	    /**
386	     * Normalizes a street address into the canonical form stored on and returned for a newly
387	     * created owner. A {@code null} value becomes the empty string; otherwise surrounding
388	     * whitespace is trimmed, internal runs of whitespace are collapsed to a single space, the
389	     * text is upper-cased, and common street-type abbreviations are expanded on a whole-word
390	     * basis ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). The normalized
391	     * value is what gets persisted, echoed back, and used for every address comparison (household
392	     * duplicate detection and the shared household identifier).
393	     *
394	     * @param rawAddress the address value as supplied by the client
395	     * @return the normalized address (possibly empty, never {@code null})
396	     */
397	    private static String normalizeAddress(String rawAddress) {
398	        if (rawAddress == null) {
399	            return "";
400	        }
401	        String collapsed = rawAddress.trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
402	        if (collapsed.isEmpty()) {
403	            return "";
404	        }
405	        String[] tokens = collapsed.split(" ");
406	        StringBuilder sb = new StringBuilder(collapsed.length());
407	        for (int i = 0; i < tokens.length; i++) {
408	            String token = tokens[i];
409	            switch (token) {
410	                case "ST" -> token = "STREET";
411	                case "RD" -> token = "ROAD";
412	                case "AVE" -> token = "AVENUE";
413	                default -> { }
414	            }
415	            if (i > 0) {
416	                sb.append(' ');
417	            }
418	            sb.append(token);
419	        }
420	        return sb.toString();
421	    }
422	
423	    /**
424	     * Builds the customer code assigned to a newly created owner. The code is formatted
425	     * {@code <REGION>-<HASH8>} where {@code REGION} is the region derived from the owner's postcode
426	     * (see {@link Owner#getRegion()}) and {@code HASH8} is the first 8 upper-case hex characters of
427	     * the SHA-256 digest of the owner's normalized (E.164) telephone concatenated with its last
428	     * name (e.g. {@code NSW-1A2B3C4D}). No sequence number is involved, so the code depends only on
429	     * the owner's own region and identity.
430	     *
431	     * @param owner the owner being created, with telephone already normalized and postcode/city set
432	     * @return the customer code to assign
433	     */
434	    private static String customerCodeFor(Owner owner) {
435	        return owner.getRegion() + "-" + telephoneNameHash(owner.getTelephone(), owner.getLastName());
436	    }
437	
438	    /**
439	     * De-duplicates a freshly computed customer code against the codes already assigned to existing
440	     * owners. When no existing owner carries the given code it is returned unchanged; otherwise the
441	     * smallest suffix {@code -<n>} with {@code n >= 2} that yields a code no existing owner holds is
442	     * appended, guaranteeing distinct owners always receive distinct customer codes.
443	     *
444	     * @param customerCode the customer code computed for the owner being created
445	     * @return the de-duplicated customer code, unique among existing owners
446	     */
447	    private String deduplicateCustomerCode(String customerCode) {
448	        java.util.Set<String> existing = this.clinicService.findAllOwners().stream()
449	            .map(Owner::getCustomerCode)
450	            .filter(java.util.Objects::nonNull)
451	            .collect(java.util.stream.Collectors.toSet());
452	        if (!existing.contains(customerCode)) {
453	            return customerCode;
454	        }
455	        int n = 2;
456	        while (existing.contains(customerCode + "-" + n)) {
457	            n++;
458	        }
459	        return customerCode + "-" + n;
460	    }
461	
462	    /**
463	     * Computes the {@code HASH8} segment of the customer code: the first 8 upper-case hex
464	     * characters of the SHA-256 digest of the normalized (E.164) telephone concatenated with the
465	     * last name.
466	     *
467	     * @param normalizedTelephone the owner's telephone in E.164 form
468	     * @param lastName the owner's last name
469	     * @return the 8-character upper-case hex hash
470	     */
471	    private static String telephoneNameHash(String normalizedTelephone, String lastName) {
472	        String key = (normalizedTelephone == null ? "" : normalizedTelephone)
473	            + (lastName == null ? "" : lastName);
474	        try {
475	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
476	                .digest(key.getBytes(java.nio.charset.StandardCharsets.UTF_8));
477	            StringBuilder sb = new StringBuilder(digest.length * 2);
478	            for (byte b : digest) {
479	                sb.append(String.format("%02x", b));
480	            }
481	            return sb.substring(0, 8).toUpperCase(java.util.Locale.ROOT);
482	        }
483	        catch (java.security.NoSuchAlgorithmException e) {
484	            throw new IllegalStateException("SHA-256 not available", e);
485	        }
486	    }
487	
488	    /**
489	     * Normalizes a telephone into E.164 form. Spaces, dashes and brackets are stripped. A value
490	     * already carrying a leading {@code '+'} keeps its country code; otherwise country code
491	     * {@code +61} is assumed and a single leading {@code '0'} is dropped from the national digits.
492	     * The result must carry a leading {@code '+'} followed by 8 to 15 digits, and the length of
493	     * the national number must match the country code: {@code +61} requires 9 national digits and
494	     * {@code +1} requires 10.
495	     *
496	     * @param rawTelephone the telephone value as supplied by the client
497	     * @return the telephone in E.164 form (e.g. {@code +61412345678})
498	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
499	     */
500	    private static String normalizeTelephone(String rawTelephone) {
501	        if (rawTelephone == null) {
502	            throw new InvalidTelephoneException(rawTelephone);
503	        }
504	        String cleaned = rawTelephone.replaceAll("[\\s\\-()]", "");
505	        String e164;
506	        if (cleaned.startsWith("+")) {
507	            String digits = cleaned.substring(1);
508	            if (!digits.matches("[0-9]+")) {
509	                throw new InvalidTelephoneException(rawTelephone);
510	            }
511	            e164 = "+" + digits;
512	        } else {
513	            if (!cleaned.matches("[0-9]+")) {
514	                throw new InvalidTelephoneException(rawTelephone);
515	            }
516	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
517	            e164 = "+61" + national;
518	        }
519	        int digitCount = e164.length() - 1;
520	        if (digitCount < 8 || digitCount > 15) {
521	            throw new InvalidTelephoneException(rawTelephone);
522	        }
523	        if (e164.startsWith("+61")) {
524	            if (e164.length() - "+61".length() != 9) {
525	                throw new InvalidTelephoneException(rawTelephone);
526	            }
527	        }
528	        else if (e164.startsWith("+1")) {
529	            if (e164.length() - "+1".length() != 10) {
530	                throw new InvalidTelephoneException(rawTelephone);
531	            }
532	        }
533	        return e164;
534	    }
535	
536	    /**
537	     * Determines whether any existing owner already carries the given identity key. The identity key
538	     * ({@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}) is the single value
539	     * all duplicate detection is based on, so two owners collide only when their whole identity keys
540	     * are equal.
541	     *
542	     * @param identityKey the identity key of the owner being created
543	     * @return {@code true} if another owner already has the same identity key
544	     */
545	    private boolean isIdentityKeyInUse(String identityKey) {
546	        return this.clinicService.findAllOwners().stream()
547	            .filter(existing -> !existing.isDeleted())
548	            .map(Owner::getIdentityKey)
549	            .anyMatch(identityKey::equals);
550	    }
551	
552	    /**
553	     * Finds an existing owner that the owner being created is a possible (soft) duplicate of: one
554	     * that shares the same last name (compared case-insensitively, whitespace-collapsed) and the
555	     * same postcode but carries a <em>different</em> telephone. Such a create is not rejected as a
556	     * hard duplicate, but is flagged. An owner with no postcode can never be a soft duplicate. When
557	     * several owners match, the earliest (lowest id) is returned so the result is deterministic.
558	     *
559	     * @param owner the owner being created (telephone already normalized, postcode set)
560	     * @return the id of the matching existing owner, or {@code null} when there is no soft match
561	     */
562	    private Integer possibleDuplicateOf(Owner owner) {
563	        if (isBlank(owner.getPostcode())) {
564	            return null;
565	        }
566	        String normalizedLastName = normalizeIdentity(owner.getLastName());
567	        return this.clinicService.findAllOwners().stream()
568	            .filter(existing -> existing.getId() != null
569	                && !existing.isDeleted()
570	                && normalizeIdentity(existing.getLastName()).equals(normalizedLastName)
571	                && owner.getPostcode().equals(existing.getPostcode())
572	                && !java.util.Objects.equals(owner.getTelephone(), existing.getTelephone()))
573	            .map(Owner::getId)
574	            .min(Integer::compareTo)
575	            .orElse(null);
576	    }
577	
578	    /**
579	     * Counts how many existing owners already share the given first name and last name with the
580	     * owner being created. Both names are compared case-insensitively (after trimming and
581	     * collapsing runs of whitespace). The count reflects the state before the new owner is
582	     * persisted, so a first, otherwise-unique owner yields {@code 0}.
583	     *
584	     * @param firstName the first name of the owner being created
585	     * @param lastName the last name of the owner being created
586	     * @return the number of existing owners sharing the same first and last name
587	     */
588	    private int namesakeCount(String firstName, String lastName) {
589	        String normalizedFirstName = normalizeIdentity(firstName);
590	        String normalizedLastName = normalizeIdentity(lastName);
591	        return (int) this.clinicService.findAllOwners().stream()
592	            .filter(existing -> normalizeIdentity(existing.getFirstName()).equals(normalizedFirstName)
593	                && normalizeIdentity(existing.getLastName()).equals(normalizedLastName))
594	            .count();
595	    }
596	
597	    /**
598	     * Counts how many members the owner being created belongs to in its household, including
599	     * itself, as of this create. Members are the owners sharing the given {@code householdId};
600	     * the new owner is not yet persisted, so its own membership is added to the existing count.
601	     * An owner not assigned to a shared household ({@code householdId} is {@code null}) is a
602	     * household of one.
603	     *
604	     * @param householdId the shared household identifier assigned to the owner being created, or
605	     *                    {@code null} if the owner does not share a household
606	     * @return the number of household members after this create (at least 1)
607	     */
608	    private int householdSizeAfterCreate(String householdId) {
609	        if (householdId == null) {
610	            return 1;
611	        }
612	        long existing = this.clinicService.findAllOwners().stream()
613	            .filter(owner -> householdId.equals(owner.getHouseholdId()))
614	            .count();
615	        return (int) existing + 1;
616	    }
617	
618	    /**
619	     * The maximum number of owners permitted in a single city. Once a city already contains this
620	     * many owners it is considered full and no further owners may be created there.
621	     */
622	    private static final int CITY_CAPACITY = 50;
623	
624	    /**
625	     * Determines whether the given city has already reached its capacity, i.e. already contains
626	     * {@value #CITY_CAPACITY} or more existing owners. Cities are compared case-insensitively after
627	     * collapsing runs of whitespace to a single space and trimming.
628	     *
629	     * @param city the city of the owner being created
630	     * @return {@code true} if the city already contains {@value #CITY_CAPACITY} or more owners
631	     */
632	    private boolean isCityAtCapacity(String city) {
633	        String normalizedCity = normalizeIdentity(city);
634	        long count = this.clinicService.findAllOwners().stream()
635	            .filter(existing -> normalizeIdentity(existing.getCity()).equals(normalizedCity))
636	            .count();
637	        return count >= CITY_CAPACITY;
638	    }
639	
640	    /**
641	     * The maximum number of owners that may be created on any single day. Once this many owners
642	     * already carry a {@code registrationDate} of the current day, no further owners may be created
643	     * that day.
644	     */
645	    private static final int DAILY_REGISTRATION_LIMIT = 100;
646	
647	    /**
648	     * Determines whether the daily registration limit has already been reached, i.e. whether
649	     * {@value #DAILY_REGISTRATION_LIMIT} or more existing owners already carry the given date as
650	     * their {@code registrationDate}.
651	     *
652	     * @param date the current day
653	     * @return {@code true} if {@value #DAILY_REGISTRATION_LIMIT} or more owners were already
654	     *         registered on the given date
655	     */
656	    /**
657	     * The fixed public holidays that the business-day roll skips. A registration date landing on
658	     * any of these is rolled forward, exactly as it is for a weekend.
659	     */
660	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
661	        LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"),
662	        LocalDate.parse("2026-04-25"), LocalDate.parse("2026-12-25"),
663	        LocalDate.parse("2026-12-28"));
664	
665	    /**
666	     * Rolls a registration date forward onto a business day. A date that already falls on a
667	     * weekday which is not a public holiday is returned unchanged; a Saturday, Sunday or listed
668	     * public holiday is rolled forward, one day at a time, until the next non-weekend,
669	     * non-holiday day is reached. This adjusted date is what gets stored as the
670	     * {@code registrationDate} and drives everything derived from it (the fiscal year, the
671	     * membership number's fiscal-year segment, the daily create-limit).
672	     *
673	     * @param date the effective registration date (supplied by the client or defaulted to the
674	     *             server's current date)
675	     * @return the same date if it is a business day, otherwise the next business day that is
676	     *         neither a weekend nor a public holiday
677	     */
678	    private static LocalDate toBusinessDay(LocalDate date) {
679	        while (isNonBusinessDay(date)) {
680	            date = date.plusDays(1);
681	        }
682	        return date;
683	    }
684	
685	    private static boolean isNonBusinessDay(LocalDate date) {
686	        DayOfWeek dayOfWeek = date.getDayOfWeek();
687	        return dayOfWeek == DayOfWeek.SATURDAY || dayOfWeek == DayOfWeek.SUNDAY
688	            || PUBLIC_HOLIDAYS.contains(date);
689	    }
690	
691	    private boolean isDailyRegistrationLimitReached(LocalDate date) {
692	        long count = this.clinicService.findAllOwners().stream()
693	            .filter(existing -> date.equals(existing.getRegistrationDate()))
694	            .count();
695	        return count >= DAILY_REGISTRATION_LIMIT;
696	    }
697	
698	    /**
699	     * The number of owners that may be created on a single day before the bulk-signup warning is
700	     * raised. Once <em>more than</em> this many owners already carry the current business day as
701	     * their {@code registrationDate}, responses flag {@code bulkSignupWarning} true.
702	     */
703	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
704	
705	    /**
706	     * Determines whether more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been
707	     * created today, i.e. already carry the current business day as their {@code registrationDate}.
708	     * This shares the daily create-limit's accumulation path (owners counted by registration date).
709	     *
710	     * @return {@code true} if more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners are already
711	     *         registered on today's business day
712	     */
713	    private boolean isBulkSignupWarning() {
714	        LocalDate today = toBusinessDay(LocalDate.now());
715	        long count = this.clinicService.findAllOwners().stream()
716	            .filter(existing -> today.equals(existing.getRegistrationDate()))
717	            .count();
718	        return count > BULK_SIGNUP_WARNING_THRESHOLD;
719	    }
720	
721	    /**
722	     * Determines whether the owner being created joins an existing household, i.e. some other owner
723	     * already carries the same computed {@code householdId} (equivalently, shares its normalized last
724	     * name and postcode). An owner with no postcode is never treated as joining a household, mirroring
725	     * the soft-duplicate rule that an owner with no postcode can never match one.
726	     *
727	     * @param owner the owner being created, with {@code householdId} already computed
728	     * @return {@code true} if another owner already belongs to the same household
729	     */
730	    private boolean isHouseholdInUse(Owner owner) {
731	        if (isBlank(owner.getPostcode())) {
732	            return false;
733	        }
734	        String householdId = owner.getHouseholdId();
735	        return this.clinicService.findAllOwners().stream()
736	            .anyMatch(existing -> existing.getId() != null
737	                && !existing.isDeleted()
738	                && householdId.equals(existing.getHouseholdId()));
739	    }
740	
741	    /**
742	     * Derives the stable household identifier for a given last name and postcode. The value is the
743	     * first 12 upper-case hex characters of the SHA-256 digest of {@code normalizedLastName + '|' +
744	     * postcode}, so it is deterministic across calls and identical for every owner sharing the same
745	     * normalized last name and postcode — they belong to the same household automatically.
746	     *
747	     * @param lastName the last name of the household
748	     * @param postcode the postcode of the household (may be {@code null})
749	     * @return the deterministic household identifier
750	     */
751	    private static String householdIdFor(String lastName, String postcode) {
752	        String key = normalizeIdentity(lastName) + "|" + (postcode == null ? "" : postcode);
753	        try {
754	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
755	                .digest(key.getBytes(java.nio.charset.StandardCharsets.UTF_8));
756	            StringBuilder sb = new StringBuilder(digest.length * 2);
757	            for (byte b : digest) {
758	                sb.append(String.format("%02x", b));
759	            }
760	            return sb.substring(0, 12).toUpperCase(java.util.Locale.ROOT);
761	        }
762	        catch (java.security.NoSuchAlgorithmException e) {
763	            throw new IllegalStateException("SHA-256 not available", e);
764	        }
765	    }
766	
767	    /**
768	     * Normalizes a text field for household-identity comparison: {@code null} becomes the empty
769	     * string, surrounding whitespace is trimmed, internal runs of whitespace are collapsed to a
770	     * single space, and the result is lower-cased.
771	     *
772	     * @param value the raw field value
773	     * @return the normalized value used for case-insensitive, whitespace-insensitive comparison
774	     */
775	    private static String normalizeIdentity(String value) {
776	        if (value == null) {
777	            return "";
778	        }
779	        return value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
780	    }
781	}
